#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
#[non_exhaustive]
pub struct ProvenanceEntry {
    /// Caller-chosen label. Never case-converted.
    pub label: String,
    /// The value for that label.
    pub value: String,
}

